    "alert_id": "EX3_ALERT_004",
    "title": "Missing Viral Load Monitoring",
    "message": "The most recent viral load is from 106 days ago. Guidelines recommend checking viral load every 6 months for patients on a DTG-based regimen. The clinician's plan does not include ordering a viral load. Regular monitoring is essential to confirm sustained virological suppression.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Order a viral load test as per the 6-month monitoring schedule for patients on DTG-based ART.",
